            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">ALCOHOL AND AFIB</text><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">What makes a study show cause?</text><text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Think back to the evidence pyramid</text><rect x=\"250\" y=\"450\" width=\"600\" height=\"160\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">RANDOMIZATION</text><text x=\"550\" y=\"565\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Balances everything but the exposure</text></svg>",
