            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Benefit vs risk, on one scale</text><rect x=\"80\" y=\"180\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"300\" y=\"250\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">BENEFIT</text><text x=\"300\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Omega-3s</text><text x=\"300\" y=\"355\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Fetal brain growth</text><rect x=\"580\" y=\"180\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"800\" y=\"250\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"26\">RISK</text><text x=\"800\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Methylmercury</text><text x=\"800\" y=\"355\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Highest in big predators</text><rect x=\"150\" y=\"580\" width=\"800\" height=\"160\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"645\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"24\">CHOOSE THE SPECIES</text><text x=\"550\" y=\"695\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"19\">Keep the benefit, shrink the risk</text></svg>",
            "caption": "Final check: choosing fish wisely"
